            Expression(Expression, Context, bool, (usize, bool)),
            Call(
                String,
                Vec<Expression>,
                Context,
                bool,
                Option<(usize, bool)>,
            ),
            Compose(
                (usize, bool),
                Vec<Expression>,
                Context,
                Option<(usize, bool)>,
            ),
            Finish((usize, bool)),
        }
        let mut tasks = vec![Task::Call(
            name.into(),
            vec![],
            context.clone(),
            purpose,
            None,
        )];
